'AC-ledger.10.1'; from __future__ import annotations; from uuid import uuid4; from httpx import AsyncClient
async def _create_account(client: AsyncClient, name: str, account_type: str) -> dict: payload = {'name': name, 'type': account_type, 'currency': 'SGD'}; resp = await client.post('/accounts', json=payload); assert resp.status_code == 201, resp.text; return resp.json()
async def test_accounts_endpoints(client: AsyncClient) -> None: 'AC-ledger.10.1'; account = await _create_account(client, 'Cash', 'ASSET'); basic_list_resp = await client.get('/accounts'); assert basic_list_resp.status_code == 200; assert basic_list_resp.json()['total'] >= 1; list_resp = await client.get('/accounts', params={'include_balance': 'true'}); assert list_resp.status_code == 200; list_data = list_resp.json(); assert list_data['total'] >= 1; assert list_data['items'][0]['balance'] is not None; filter_resp = await client.get('/accounts', params={'account_type': 'ASSET'}); assert filter_resp.status_code == 200; get_resp = await client.get(f"/accounts/{account['id']}"); assert get_resp.status_code == 200; assert get_resp.json()['id'] == account['id']; update_resp = await client.put(f"/accounts/{account['id']}", json={'name': 'Cash Vault', 'code': '1001', 'description': 'Updated'}); assert update_resp.status_code == 200; assert update_resp.json()['name'] == 'Cash Vault'; deactivate_resp = await client.put(f"/accounts/{account['id']}", json={'is_active': False}); assert deactivate_resp.status_code == 200; assert deactivate_resp.json()['is_active'] is False; inactive_resp = await client.get('/accounts', params={'is_active': 'false'}); assert inactive_resp.status_code == 200; assert inactive_resp.json()['total'] >= 1; missing_resp = await client.get(f'/accounts/{uuid4()}'); assert missing_resp.status_code == 404; missing_update = await client.put(f'/accounts/{uuid4()}', json={'name': 'Missing'}); assert missing_update.status_code == 404
async def test_AC_ledger_2674_1_system_accounts_cannot_be_updated_or_deleted(client: AsyncClient, db, test_user) -> None:
    'AC-ledger.2674.1'; import pytest; from src.ledger import ValidationError, account_service, get_or_create_processing_account; from src.schemas.account import AccountUpdate; sys_account = await get_or_create_processing_account(db, test_user.id, currency='SGD'); await db.commit()
    with pytest.raises(ValidationError, match='System accounts cannot be modified or deleted'): await account_service.update_account(db, test_user.id, sys_account.id, AccountUpdate(name='Renamed System'))
    update_resp = await client.put(f'/accounts/{sys_account.id}', json={'name': 'Renamed System'}); assert update_resp.status_code == 400; assert 'System accounts cannot be modified or deleted' in update_resp.json()['detail']; delete_resp = await client.delete(f'/accounts/{sys_account.id}'); assert delete_resp.status_code == 400; assert 'System accounts cannot be modified or deleted' in delete_resp.json()['detail']; from src.ledger.orm.account import Account, AccountType; from src.portfolio.extension.positions import PositionService; inactive_broker = Account(user_id=test_user.id, name='Moomoo SG', type=AccountType.ASSET, currency='SGD', code='AUTO-ASSET', is_active=False); db.add(inactive_broker); await db.commit(); resolved_broker = await PositionService()._get_or_create_broker_account(db, user_id=test_user.id, broker_name='Moomoo SG', currency='SGD'); assert resolved_broker.id != inactive_broker.id; assert resolved_broker.is_active is True
